import unittest
from vclock.clock import VectorClock

class TestVClock(unittest.TestCase):
    def test_causality(self):
        c1 = VectorClock('a'); c1.tick()
        c2 = VectorClock('b'); c2.merge(c1.clock)
        self.assertTrue(c1.happens_before(c2))

if __name__ == '__main__': unittest.main()

