class VectorClock:
    def __init__(self, node_id: str):
        self.node_id = node_id
        self.clock: dict[str, int] = {node_id: 0}

    def tick(self) -> None:
        self.clock[self.node_id] += 1

    def merge(self, other: dict[str, int]) -> None:
        for k, v in other.items():
            self.clock[k] = max(self.clock.get(k, 0), v)
        self.tick()

    def happens_before(self, other: 'VectorClock') -> bool:
        less_or_equal = all(self.clock.get(k, 0) <= other.clock.get(k, 0) for k in self.clock)
        strict_less = any(self.clock.get(k, 0) < other.clock.get(k, 0) for k in other.clock)
        return less_or_equal and strict_less
